    "table": "samp_custom_sw_publisher"
  },
  {
    "kpi": "Custom PPN",
    "usecase": "Custom PPN refers to unique product part numbers added to track specialized or custom-configured products for inventory, procurement, or licensing purposes.",
    "recommendation": "Ensure accurate mapping of custom PPNs and audit to prevent mismatches.",
    "field": "active=true",
    "table": "samp_custom_sw_product_definition"
  },
  {
    "kpi": "Custom Dmap",
    "usecase": "Custom Dmap is used for defining custom data mappings to facilitate integration or reporting requirements for non-standardized data structures.",
